#ifndef VOXEL_PLANET_HASH_NOISE_SHADER_H
#define VOXEL_PLANET_HASH_NOISE_SHADER_H

// GLSL twin of core/math/planet_hash_noise.h.
//
// These two must stay bit-identical. Every operation used here (uint32 multiply, xor, right shift,
// int->uint reinterpretation, float multiply-add, floor) is exactly specified in both C++ and GLSL,
// so the results match rather than merely being close. If you edit one file, edit the other, and
// re-run `--run_planet_field_bench`, which cross-checks the two paths.
//
// Hand-written, not generated by shaders/text2cpp.py, because it has a C++ counterpart that has to be
// kept in step by hand anyway.


const char *const g_planet_hash_noise_shader = R"(

uint zn_planet_hash_u32(uint x) {
	x ^= x >> 16;
	x *= 0x7feb352du;
	x ^= x >> 15;
	x *= 0x846ca68bu;
	x ^= x >> 16;
	return x;
}

uint zn_planet_hash_coords(int xi, int yi, int zi, uint seed) {
	uint h = seed;
	h += uint(xi) * 0x27d4eb2du;
	h += uint(yi) * 0x85ebca6bu;
	h += uint(zi) * 0xc2b2ae35u;
	return zn_planet_hash_u32(h);
}

float zn_planet_grad_3d(uint hash, float x, float y, float z) {
	uint h = hash & 15u;
	float u = (h < 8u) ? x : y;
	float v = (h < 4u) ? y : ((h == 12u || h == 14u) ? x : z);
	return ((h & 1u) == 0u ? u : -u) + ((h & 2u) == 0u ? v : -v);
}

// Deliberately not GLSL's `mix`: mix(a,b,t) evaluates a*(1-t)+b*t, which differs in the low bits
// from the a+t*(b-a) form used on the C++ side. Bit-identity is the entire point of this file.
float zn_planet_lerp(float a, float b, float t) {
	// `precise` forbids the shader compiler from fusing this into an FMA. The C++ side
	// disables contraction for the same reason; if either side fuses and the other does
	// not, the two disagree in the low bits and the surfaces separate at chunk seams.
	precise float r = a + t * (b - a);
	return r;
}

float zn_planet_fade(float t) {
	precise float r = t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
	return r;
}

float zn_planet_perlin_3d(float x, float y, float z, uint seed) {
	float fx = floor(x);
	float fy = floor(y);
	float fz = floor(z);

	int xi = int(fx);
	int yi = int(fy);
	int zi = int(fz);

	float dx = x - fx;
	float dy = y - fy;
	float dz = z - fz;

	float u = zn_planet_fade(dx);
	float v = zn_planet_fade(dy);
	float w = zn_planet_fade(dz);

	float dx1 = dx - 1.0;
	float dy1 = dy - 1.0;
	float dz1 = dz - 1.0;

	float n000 = zn_planet_grad_3d(zn_planet_hash_coords(xi, yi, zi, seed), dx, dy, dz);
	float n100 = zn_planet_grad_3d(zn_planet_hash_coords(xi + 1, yi, zi, seed), dx1, dy, dz);
	float n010 = zn_planet_grad_3d(zn_planet_hash_coords(xi, yi + 1, zi, seed), dx, dy1, dz);
	float n110 = zn_planet_grad_3d(zn_planet_hash_coords(xi + 1, yi + 1, zi, seed), dx1, dy1, dz);
	float n001 = zn_planet_grad_3d(zn_planet_hash_coords(xi, yi, zi + 1, seed), dx, dy, dz1);
	float n101 = zn_planet_grad_3d(zn_planet_hash_coords(xi + 1, yi, zi + 1, seed), dx1, dy, dz1);
	float n011 = zn_planet_grad_3d(zn_planet_hash_coords(xi, yi + 1, zi + 1, seed), dx, dy1, dz1);
	float n111 = zn_planet_grad_3d(zn_planet_hash_coords(xi + 1, yi + 1, zi + 1, seed), dx1, dy1, dz1);

	float x00 = zn_planet_lerp(n000, n100, u);
	float x10 = zn_planet_lerp(n010, n110, u);
	float x01 = zn_planet_lerp(n001, n101, u);
	float x11 = zn_planet_lerp(n011, n111, u);

	float y0 = zn_planet_lerp(x00, x10, v);
	float y1 = zn_planet_lerp(x01, x11, v);

	return zn_planet_lerp(y0, y1, w) * 1.1547005383792515;
}

float zn_planet_fbm_3d(float x, float y, float z, uint seed, float period, int octaves,
		float lacunarity, float gain) {
	float freq = 1.0 / period;
	float amp = 1.0;
	float sum = 0.0;
	float norm = 0.0;
	for (int i = 0; i < octaves; ++i) {
		precise float contrib = amp * zn_planet_perlin_3d(x * freq, y * freq, z * freq, seed + uint(i));
		sum += contrib;
		norm += amp;
		freq *= lacunarity;
		amp *= gain;
	}
	return norm > 0.0 ? sum / norm : 0.0;
}

)";


#endif // VOXEL_PLANET_HASH_NOISE_SHADER_H
